import {makeAsset,makeNoodleDish,makeSushiDish} from './imported-food.js';
import * as T from './vendor/three.module.js';
import {makeFood} from './food-models.js';
import {recipes} from './recipe-catalog.js';
export function makeDish(id){const r=recipes[id];if(!r)throw Error('Unknown recipe '+id);if(id==='sushi')return makeSushiDish();if(id.endsWith('noodles'))return makeNoodleDish(id);let g;if(['omelet','toast','milk','fruitsalad'].includes(id)){g=new T.Group();const add=(geo,color,x,y,z,sx=1,sy=1,sz=1)=>{const m=new T.Mesh(geo,new T.MeshStandardMaterial({color,roughness:.8}));m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m};if(id==='milk'){add(new T.CylinderGeometry(.10,.085,.24,24),0xc4d5c5,0,.13,0);add(new T.CylinderGeometry(.089,.089,.008,24),0xf0dacd,0,.254,0);}else if(id==='omelet'){add(new T.CylinderGeometry(.27,.27,.022,32),0xf4ead3,0,.02,0);add(new T.SphereGeometry(1,24,16),0xe4bc63,0,.09,0,.22,.07,.13);for(let j=0;j<4;j++)add(new T.BoxGeometry(.023,.009,.12),0xc57759,-.1+j*.062,.158,0);}else{add(new T.CylinderGeometry(.18,.12,.13,24),0xaac2b1,0,.08,0);add(new T.CylinderGeometry(.167,.167,.01,24),id==='toast'?0xe7d090:0xf3e7d2,0,.15,0);if(id==='fruitsalad')for(const [f,x]of [['strawberry',-.065],['blueberry',.07]]){const top=makeFood(f);top.scale.setScalar(.45);top.position.set(x,.16,0);g.add(top)}}}else g=makeFood(r.model==='meal'?'chickenmeal':r.model);if(['beefrice','beefnoodles','shrimpnoodles','mushroomnoodles','shrimprice','beefstew','tofusoup'].includes(id)){const key=id.startsWith('beef')?'beef':id.includes('shrimp')?'shrimp':id==='tofusoup'?'tofu':'mushroom';const topping=key==='beef'?makeAsset('meatcookedslice',.3):makeFood(key);topping.scale.setScalar(.38);topping.position.set(.03,.19,0);g.add(topping)}return g}
